package com.forgeci.application.repository;
import com.forgeci.application.auth.AuthException; import com.forgeci.application.github.*; import com.forgeci.application.organization.OrganizationService; import com.forgeci.domain.repository.*; import com.forgeci.infrastructure.organization.OrganizationRepository; import com.forgeci.infrastructure.repository.RepositoryRepository; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class RepositoryService { private final RepositoryRepository repositories; private final OrganizationRepository organizations; private final OrganizationService organizationService; private final GitHubConnectionService connections; private final GitHubClient github; public RepositoryService(RepositoryRepository r,OrganizationRepository o,OrganizationService os,GitHubConnectionService c,GitHubClient g){repositories=r;organizations=o;organizationService=os;connections=c;github=g;} public List<Repository> list(UUID userId,UUID orgId){requireMember(userId,orgId);return repositories.findAllByOrganizationId(orgId);} @Transactional public Repository connect(UUID userId,UUID orgId,String externalId) throws Exception {requireManager(userId,orgId);var org=organizations.findById(orgId).orElseThrow(()->new AuthException("ORGANIZATION_NOT_FOUND","Organization not found"));var remote=github.repositories(connections.token(userId,orgId)).stream().filter(r->r.id().equals(externalId)).findFirst().orElseThrow(()->new AuthException("REPOSITORY_NOT_FOUND","GitHub repository not found or inaccessible"));var existing=repositories.findByOrganizationIdAndProviderAndExternalId(orgId,RepositoryProvider.GITHUB,externalId);if(existing.isPresent()){existing.get().refresh(remote.name(),remote.fullName(),remote.cloneUrl(),remote.defaultBranch(),remote.privateRepository());return repositories.save(existing.get());}return repositories.save(new Repository(org,RepositoryProvider.GITHUB,remote.id(),remote.name(),remote.fullName(),remote.cloneUrl(),remote.defaultBranch(),remote.privateRepository()));} @Transactional public void disconnect(UUID userId,UUID orgId,UUID repositoryId){requireManager(userId,orgId);var r=repositories.findById(repositoryId).orElseThrow(()->new AuthException("REPOSITORY_NOT_FOUND","Repository not found"));if(!r.getOrganization().getId().equals(orgId))throw new AuthException("REPOSITORY_NOT_FOUND","Repository not found");repositories.delete(r);} @Transactional public Repository refresh(UUID userId,UUID orgId,UUID repositoryId) throws Exception {requireManager(userId,orgId);var r=repositories.findById(repositoryId).orElseThrow(()->new AuthException("REPOSITORY_NOT_FOUND","Repository not found"));var remote=github.repositories(connections.token(userId)).stream().filter(x->x.id().equals(r.getExternalId())).findFirst().orElseThrow(()->new AuthException("REPOSITORY_NOT_FOUND","GitHub repository is no longer accessible"));r.refresh(remote.name(),remote.fullName(),remote.cloneUrl(),remote.defaultBranch(),remote.privateRepository());return repositories.save(r);} public List<GitHubClient.GitHubRepository> available(UUID userId) throws Exception{return github.repositories(connections.token(userId));} private void requireMember(UUID u,UUID o){if(!organizationService.isMember(u,o))throw new AuthException("FORBIDDEN","Organization membership required");} private void requireManager(UUID u,UUID o){if(!organizationService.canManage(u,o))throw new AuthException("FORBIDDEN","Organization administrator access required");}}
